        ObservationService.WriteOutcome outcome = observationService.merge(observationId, request);
        return ResponseEntity.status(outcome.status()).body(outcome.body());
    }

    /**
     * 删除观测记录：expectedVersion 匹配当前版本时生成新版本墓碑。
